INSERT INTO public.tarefas VALUES ('7da4bcfa-2499-4272-b3e7-8114d5b971ad', '30a7b72a-34cf-4e63-93e6-e40d64754e2c', 'Cobrar levantamento de casamentos com gasto > R$100k', 'Vitor pediu para alguém da equipe (não identificado no áudio) levantar quantos casamentos tiveram gasto acima de R$100 mil e enviar o resultado até amanhã. Se não chegar, ele precisa cobrar a entrega.', '?', DEFAULT, NULL, 'amanhã', 'alta', 'concluida', 'Faz o seguinte, vê pra mim quantos casamentos o pessoal gastou mais que cem mil, beleza? E aí pode me mandar amanhã, sem problema.', '2026-05-18 20:51:44.449357+00', '2026-05-25 23:42:44.883927+00', '2026-05-21 22:34:14.802406+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'aguardar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3e9bd6e8-5084-443f-a4d8-dd5a38b461d0', 'eccbdc34-cd1a-4ab8-8607-934a52ae2036', 'Estruturar e comunicar modelo de acesso ao GPT pago para o time', 'Resolver a confusão sobre onde está o acesso ao GPT pago/Cloud (ex.: link divulgado só no hackathon), definir como as pessoas solicitam acesso e garantir que quem precisa (como Sofia do corporativo) saiba como usar a conta corporativa.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Aí eu falei assim, não, tem. Aí eu fui procurar onde tá, né, e não tá, né. A gente divulgou uma vez no Hackathon. Pegar dinheiro, Victor. Mas eu fui, vai que, né. / a Sofia do corporativo... queria, sei lá, explorar mais e entender como', '2026-05-25 18:31:36.969674+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('960b52eb-d882-4aa1-b679-ee1de809980c', 'eccbdc34-cd1a-4ab8-8607-934a52ae2036', 'Garantir onboarding e escopo do novo CRM focado em cross-sell Weddings → Trips', 'Acompanhar a entrada do fornecedor/"cara do CRM" e alinhar com Diana e Marcelo o escopo de uso do CRM para trabalhar a base (casais, convidados) e medir conversão de clientes de weddings em clientes de trips, saindo do estado de espera passiva.', 'vitor', DEFAULT, NULL, 'entrada do cara do CRM', 'alta', 'aberta', 'E a contratação do CRM vem para ocupar esse espaço. Então é porque eu tenho como Marcelo o desejo de começar a entender quanto eu consigo virar de clientes de weddings para clientes de trips. / eu tô esperando sempre o o cara do CRM, e isso me incomoda porque eu não vejo as nossas ações ali.', '2026-05-25 18:31:36.969674+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('7cc7a81d-0bbb-40d9-9edf-9eb67309f4a0', '667d5ccf-40c0-4334-afc3-4523774c8163', 'Acompanhar mapeamento de processos e problemas com a Ana', 'Vitor combinou com a Ana que precisa muito da ajuda dela para mapear todos os processos, organizar os problemas (especialmente o fluxo da Rafa e convidados) e estruturar soluções. Acompanhar esse mapeamento e garantir que ela avance nisso.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'eu preciso muito da sua ajuda pra gente mapear tudo isso e andar com tudo isso.', '2026-05-26 16:33:16.953557+00', '2026-05-26 16:33:16.953557+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('484680da-2312-4770-85e1-11a7703302bc', '667d5ccf-40c0-4334-afc3-4523774c8163', 'Cobrar da Ana o detalhamento do problema 1 em subproblemas e soluções', 'Vitor pediu que a Ana pegue o problema principal (processo de extras/convidados) e o que já foi mapeado, quebre em subproblemas (proatividade de contato, clareza de quem são os convidados, datas, fluxo de mensagens etc.) e proponha soluções para discutirem juntos. Vitor deve acompanhar e cobrar esse material se não vier.', 'Ana', DEFAULT, NULL, NULL, 'alta', 'aberta', 'eu preciso muito da sua ajuda pra gente mapear tudo isso e andar com tudo isso. [...] Então pegar esses problemas e quebrar ele em subproblemas e as soluções.', '2026-05-26 16:33:17.262758+00', '2026-05-26 16:33:17.262758+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('545a0c5f-283f-4b8a-833e-e9c193150857', '667d5ccf-40c0-4334-afc3-4523774c8163', 'Cobrar da Ana a marcação da conversa de follow-up amanhã depois do almoço', 'Vitor combinou com a Ana de continuar a conversa amanhã, pediu para evitar o horário de almoço e que ela escolha um horário depois do almoço, já que a agenda dele está livre. Vitor deve conferir se esse horário foi marcado.', 'Ana', DEFAULT, '2026-05-27 00:00:00+00', 'amanhã depois do almoço', 'alta', 'concluida', 'A gente consegue falar amanhã? [...] Não vamos no meu horário porque impacta no seu almoço. A gente pode ir depois do almoço. [...] Você vê um horário que tá bom para você, que minha agenda tá livre, e bora.', '2026-05-26 16:33:17.262758+00', '2026-05-26 17:43:49.154016+00', '2026-05-26 17:43:49.154016+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('fdeae2a2-3c9a-44e0-b3b0-52ad1b507ace', '667d5ccf-40c0-4334-afc3-4523774c8163', 'Marcar e realizar conversa com Ana amanhã depois do almoço para discutir soluções', 'Vitor combinou com a Ana de falar novamente amanhã depois do almoço para discutir as soluções dos problemas mapeados. Ele pediu para ela ver um horário que fique bom para ela, considerando que a agenda dele está livre; precisa garantir que esse horário seja combinado e a conversa aconteça.', 'vitor', DEFAULT, '2026-05-27 15:00:00+00', 'amanhã depois do almoço', 'alta', 'concluida', 'A gente consegue falar amanhã?
INSERT INTO public.tarefas VALUES ('7e0496c8-9d90-4ed2-8db3-cff7058e07b6', '667d5ccf-40c0-4334-afc3-4523774c8163', 'Mapear processo da Mari antes das férias de agosto', 'Vitor identificou que ninguém sabe fazer o que a Mari faz e que ela sai de férias em agosto; ele precisa garantir que o processo dela seja mapeado e documentado antes das férias para reduzir risco operacional e avaliar automações.', 'Ana', DEFAULT, '2026-06-02 02:59:00+00', 'antes das férias da Mari em agosto', 'alta', 'aberta', 'Hoje aliás eu acho que isso é um problema, porque quando a Mari sai de férias ninguém sabe fazer o que ela faz. ... Então, tipo, em agosto ela sai de férias.', '2026-05-26 17:23:41.536049+00', '2026-05-26 17:54:46.89747+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('69bd4394-2e36-4904-8c28-268f82b36e70', 'd82e2351-4d9f-4dd0-ae4a-497d10cf93c6', 'Verificar como criar tarefas para viagens já fechadas', 'Entender no sistema/processo atual qual é o fluxo correto para criar tarefas associadas a viagens que já foram encerradas/fechadas.', 'vitor', DEFAULT, '2026-05-29 02:59:00+00', 'sexta', 'alta', 'aberta', 'Preciso verificar como fazer para criar tarefas de viagens que já fecharam.', '2026-05-18 19:04:35.913898+00', '2026-05-26 17:57:06.139318+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b1233838-7142-444d-8d2b-058d3624ee6e', 'f8c50470-5ad5-4db5-94bb-01484d364fcf', 'Priorizar implementação da calculadora/pontuação no TARS após consolidar dados e atendimento', 'Depois de ter certeza absoluta dos dados e de a Patrícia estar atendendo bem com o fluxo redondo, implementar a calculadora/pontuação no TARS para integrar com as automações.', 'vitor', DEFAULT, NULL, 'após consolidar dados e atendimento da Patrícia', 'media', 'aberta', 'Na verdade, o TARS é a terceira prioridade… a primeira é os dados, a segunda é a Patrícia atendendo bonitinho… e aí a outra é tá no TARS, certinho', '2026-05-27 19:02:07.799431+00', '2026-05-27 19:02:07.799431+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('6d126e54-6c1d-4bff-98dc-412b1ce822f4', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Finalizar dash de Trips e analytics de Weddings até terça', 'Victor se comprometeu a terminar o dash de Trips e a parte de analytics de Weddings (incluindo análise de contratos fechados e índice da ''mentira'') até terça, para alimentar decisões sobre funil e leads.', 'vitor', DEFAULT, NULL, 'até terça de manhã ou quarta', 'alta', 'aberta', 'esse tá até terça de manhã ou quarta, né, que é o prazo para eu terminar o analytics de weddings dessa parte, vai estar lá.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('85599d95-1862-4d70-a7b2-48dd8a0cc369', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Concluir ajustes na SDR agente de IA', 'Victor está refazendo a SDR agente de IA após quebrar ao tentar uma mudança e precisa deixá-la estável, sem erros como repetição de mensagens, antes de liberar em produção.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'a SDR agêntica, né, de IA, eu comecei a— ela não estava, não está ainda do jeito que tem que ser, que ela ainda está errando coisa besta... eu quebrei ela e tô refazendo.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b6b326af-5b5a-46a1-a2db-04e69b8d1e64', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Acompanhar diagnóstico de CRM e plano de prazos com Fernanda', 'Vitor já passou o plano de ação de CRM para a Fernanda; ela está com o Active conectado, olhando tudo, fechando o diagnóstico e depois vai propor prazos. Vitor deve acompanhar e cobrar se ela não trouxer diagnóstico e cronograma.', 'Fernanda', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Ela já tá olhando, então ela tá com o Active conectado no cloud dela e tá olhando tudo. E ela tá trabalhando já para poder primeiro fechar esse diagnóstico e depois trabalhar com a gente uma ideia de prazos', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('12280f4c-1ba2-4868-8ec5-26f073627fa9', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Cobrar da Vanessa o download das transcrições do Elephant', 'Vitor pediu para a Vanessa falar com o pessoal do Elephant para baixar todas as transcrições, mas ainda não cobrou o retorno. Ele precisa cobrar se ela conseguiu o acesso/arquivo para poder rodar análise retroativa e ajustar o score no Elephant.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Eu pedi para Vanessa falar com o pessoal do Elephant para a gente baixar todas as transcrições. [...] Só que eu não cobrei a Vanessa ainda do retorno, do se ela conseguiu isso', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('552d54b6-a665-4544-b9bf-f8b0288f6093', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Incluir número de venda, pagante e CPF na planilha de casamentos', 'Na limpeza da base de casamentos, Vitor combinou de adicionar número de venda do Mondi, campo de pagante e CPF na planilha para permitir leitura única e cruzar com o Active.', 'vitor', DEFAULT, NULL, 'agora / nesta rodada de limpeza', 'media', 'aberta', 'Eu colocaria porque a gente cria meio que um ID [...] Então já me interessa, pagante. [...] Vou colocar aqui, venda pagante. Isso, venda pagante. CPF que tá aí já. E o CTF, eu vou colocar ele junto também', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c9060871-9b76-462d-a8a1-13fc2a1fee4a', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Finalizar analytics de Weddings incluindo análise de contratos fechados', 'Vitor se comprometeu a até terça/quarta terminar o analytics de Weddings, incluindo análise dos contratos que fecharam (investimento, número de convidados, limpeza de 20% restantes da base e correções no Mondi).', 'vitor', DEFAULT, '2026-06-03 23:59:59+00', 'até terça de manhã ou quarta', 'urgente', 'aberta', 'Esse tá até terça de manhã ou quarta, né, que é o prazo para eu terminar o analytics de weddings dessa parte, vai estar lá. [...] já tá 80%, ainda falta 20% do negócio de preenchimento errado', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('6b52094b-03dc-49f4-b758-873b9dc9f51a', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Concluir dashboard de Trips e validar se está correto', 'Vitor tinha que terminar o dashboard de Trips, mas ainda não validou se está correto e por isso não entregou. Ele precisa revisar, validar e concluir esse dash.', 'vitor', DEFAULT, '2026-06-02 23:59:59+00', 'esta semana / até a próxima reunião', 'alta', 'aberta', 'Eu tinha que terminar o Dash de trips, que eu não avaliei se tá correto ainda, então eu não vou entregar, ok?', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3a70417a-9443-464d-a9d6-297b573b7137', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Rodar análise retroativa de score usando dados do Elephant', 'Após conseguir baixar as transcrições do Elephant, Vitor pretende rodar score retroativo para entender o que aconteceu e ajustar o Elephant para ter score parecido com o modelo atual.', 'vitor', DEFAULT, NULL, 'depois de baixar todas as transcrições', 'media', 'aberta', 'Se baixar todas, eu consigo rodar aqui para ele fazer retroativo. E aí a gente ajustar o elefante para ele ter o score parecido', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('eea0be58-a0eb-4474-9724-d25f823cff3f', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Ajustar e estabilizar a SDR agente de IA antes de soltar em produção', 'Vitor está refazendo a SDR agente de IA porque ela ainda erra coisas básicas e repete mensagens; ele quebrou ao tentar mudar e precisa corrigir e estabilizar antes de liberar.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'A SDR agêntica de IA [...] ainda está errando coisa besta. [...] quando eu fui fazer uma mudança lá eu quebrei ela e tô refazendo. [...] eu não consigo nem falar prazo porque eu tô o dia todo é ela e o analytics', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d02d5b88-3dc0-4c26-9ef7-42d09a5dff81', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Finalizar dashboard de Weddings para alimentar parte de vendas e duplicados', 'Vitor está construindo um dash que vai alimentar a parte de vendas, mostrar duplicados e o que está acontecendo; ele se comprometeu a deixá-lo pronto até terça.', 'vitor', DEFAULT, '2026-06-02 23:59:59+00', 'até terça que vem', 'urgente', 'aberta', 'o meu Dash que eu tô fazendo, ele vai alimentar essa parte também [...] Então é o que tá para terça que vem, sacou?', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('1225204d-1117-45d1-8120-f57a6fc37fb8', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Organizar com Fernanda um relatório de acompanhamento de CRM e próximos passos', 'Vitor combinou que vai organizar com a Fernanda um relatório para acompanhamento dos indicadores de CRM e dos próximos passos do plano de ação.', 'vitor', DEFAULT, NULL, 'próximos dias', 'media', 'aberta', 'Aí eu vou organizar com a Fernanda um relatório para a gente poder ter de acompanhamento e dos próximos passos', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c7fedc8d-dd08-41c2-9a24-9146455163f5', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Agendar reunião com Duyan para revisar origem e qualidade dos dados do Mondi', 'Vitor já marcou para hoje às 16h uma reunião com o Duyan para entender de onde ele está puxando os dados do Mondi, validar campos faltantes e corrigir problemas de receita, dias e locais.', 'vitor', DEFAULT, '2026-05-29 16:00:00+00', 'hoje às 4', 'urgente', 'aberta', 'Eu tenho reunião com o Duyan quando acabar aqui a nossa, umas 4. Que é, cara, eu não sei da onde ele tá puxando os dados', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('1a4971d9-4992-4e64-bff8-949e31858232', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Falar com Matheus sobre o comportamento de dizer não primeiro', 'Conversar diretamente com o Matheus para alinhar que ele pare de responder ''não'' de primeira, passe a avaliar e dizer ''vou ver'' antes de negar, pois isso está impactando negativamente a velocidade das entregas.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'eu tenho que falar com o Matteus, porque o Matteus tem o comportamento de falar não primeiro. Falando, para de falar não primeiro. Falando, vou ver, e depois você fala não.', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c6306463-8009-4061-92fd-7226ce8e6c41', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Marcar reunião de acompanhamento na quarta à tarde sobre leads e próximos passos', 'O grupo combinou de deixar marcado para quarta à tarde uma reunião mais estratégica para ver andamento e próximos passos em relação ao que for decidido na terça sobre leads.', 'vitor', DEFAULT, '2026-06-03 15:00:00+00', 'quarta-tarde', 'alta', 'aberta', 'vocês acham que a gente pode deixar marcado para quarta-tarde a gente sentar para ver o andamento ou minimamente os próximos passos em relação ao que a gente decidiu na terça?', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d30dc884-9820-4bf5-86fc-ba77259d5af1', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Cobrar da Ana o mapeamento completo dos processos e problemas de convidados', 'Vitor combinou de orientar a Ana a mapear tudo (processos, problemas, tipos de comunicação, etc.) na área de convidados e trazer esse levantamento para ele, como base para redesenhar o fluxo e dar feedbacks.', 'Ana', DEFAULT, '2026-05-28 02:59:00+00', NULL, 'alta', 'aberta', 'Ana, pega e mapeia tudo e me traz, e aí eu faço uma reunião. Tipo, a gente vai mudar 5% do que...', '2026-05-20 15:08:39.694608+00', '2026-05-26 17:43:56.749059+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'aguardar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('28a364a4-bf86-4f6d-8f70-48683c4b28ab', 'bff0f2e9-e4dd-450f-a730-4147c36d5129', 'Garantir que dashboards e dados apresentados na terça estejam redondos', 'Vitor reforçou que até terça o dash dele estará redondinho e alinhado com o de outra pessoa, para depois juntar os dois e ter visão ponta a ponta; ele precisa revisar e validar antes da reunião.', 'vitor', DEFAULT, '2026-06-02 23:59:59+00', 'para terça', 'urgente', 'aberta', 'O meu aqui para terça-feira vai estar redondinho também. É, aí a gente, o de terça é o meu também, aí depois a gente põe mais um prazo para juntar os dois', '2026-06-02 17:45:49.223386+00', '2026-06-02 17:45:49.223386+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('01ba1b6d-eae1-4ded-8c10-eb955a41ba0a', '0e7ad5e7-5502-4ba7-8fb1-273ad33a1241', 'Passar o desenho do projeto de relatórios/alertas para o Mateus implementar aos poucos', 'Vitor comentou que já tem todo o desenho e algumas partes feitas de um projeto (incluindo alertas de mensagens sem resposta e números do corporativo) e que vai passar isso para o Mateus ir implementando aos poucos, conciliando com outras demandas dele.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Só que eu vou fazer, eu vou passar pro Mateus, porque eu já tenho todo o desenho, já fiz algumas coisas, e aí a gente vai coloco pra ele ir fazendo aos poucos, sabe, porque ele também tá com os negócios', '2026-05-20 18:49:29.141515+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('0afc709d-2324-4ca4-bb61-ccf63cb5c44d', 'eccbdc34-cd1a-4ab8-8607-934a52ae2036', 'Criar rito de comunicação de mudanças de processos e sistemas para times impactados', 'Definir um padrão para avisar previamente as equipes sobre mudanças em mensagens, fluxos de CRM, testes em produção etc. (o que vai mudar, quando, possíveis efeitos colaterais), para reduzir resistência e ruídos como duplicação de leads e mensagens inesperadas.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Aqui eu coloquei em amarelo, Vitor, que eu acho que é uma coisa que a gente tá falhando enquanto gestão, que é... A gente tem feito muitas iniciativas e tem comunicado muito pouco com as pessoas que são impactadas no processo... pode ser que, né, duplique os leads, pode ser que a mensagem mude, enfim', '2026-05-25 18:31:36.969674+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d5bb1441-9d65-496b-a82e-5c802bba345d', '3eb8bc83-0325-43ba-8869-b37c4375b950', 'Receber da Ana o levantamento das noivas para contato no Monde', 'Vitor pediu para a Ana puxar no Monde quais são as noivas com quem precisam conversar e combinou de falar melhor sobre isso amanhã. Aguardar esse levantamento e cobrar se não chegar até amanhã.', 'Ana', DEFAULT, NULL, 'amanhã', 'alta', 'concluida', 'Ana, tudo bem? Então, faz o seguinte, puxa lá no Monde quais são as noivas que a gente precisa conversar e aí amanhã a gente fala melhor sobre isso', '2026-05-18 21:26:05.166867+00', '2026-05-25 23:42:44.883927+00', '2026-05-21 22:34:21.697091+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'aguardar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('336cb2f6-4ce1-48ca-9707-37b1d1ae0f06', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Marcar reunião com dois interlocutores para discutir o projeto de enquadramento da vaga', 'Vitor disse que vai pegar um modelo e marcar uma reunião com os dois interlocutores para discutir a parte do projeto de enquadramento da vaga da pessoa responsável por convidados.', 'vitor', DEFAULT, NULL, 'marcar reunião para discutir projeto de enquadramento', 'media', 'aberta', 'Tá, eu vou pegar o modelo e vou marcar uma reunião com vocês dois pra gente discutir a parte do projeto de enquadramento, ok?', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b2247600-5e83-4295-a83b-675e197e26b2', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Conversar com as meninas de convidados sobre o novo arranjo e teste com Vitor tocando convidados', 'Vitor e o grupo combinaram que ele vai tocar convidados como teste, com passagem de bastão clara para as meninas de convidados, explicando que é um teste e que podem ajustar se não funcionar.', 'vitor', DEFAULT, NULL, 'hoje ou em breve ("vamos falar hoje já")', 'alta', 'aberta', 'Então ficamos combinados que fica comigo, e aí eu acho que a gente tem que fazer uma passagem de bastão mesmo, clara, o Victor vai tocar convidados. ... Vamos falar hoje já com as meninas convidadas?', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('9b2fea80-a991-4b7b-a3c1-755d664ade81', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Participar da reunião de terça para fechar a descrição da vaga de convidados', 'Vitor se comprometeu a participar da reunião de terça com o grupo para revisar o texto da vaga que ele enviará e bater o martelo na versão final.', 'vitor', DEFAULT, NULL, 'terça', 'media', 'concluida', 'Então, vamos marcar então sexta, dezesseis, porque sim, acho que vocês vão ter que contribuir muito pra es pra escrever a vaga. ... Então a gente deixa a reunião para segunda e eu mando até sexta, ok? ... põe na terça.', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', '2026-05-21 22:34:35.502116+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3fcd314c-fb1a-4494-be90-5d4ee989f522', 'c7896b53-7008-4cdc-82ed-6900220327ee', 'Cobrar consolidação das planilhas e documentos de casamentos em um repositório único', 'Garantir que alguém da equipe junte todas as planilhas e documentos relevantes de casamentos (orçamentos, documentos de hotel, produção etc.) em um lugar organizado, priorizando dados em que há maior certeza, para posterior análise com IA.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'A gente precisa de todas essas planilhas aí, juntar o que a gente tem certeza do dado.', '2026-06-08 13:00:46.344362+00', '2026-06-08 13:00:46.344362+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Ana", "Isa"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('3d917691-c7e2-43fa-9585-b7097bb5c2f2', 'c7896b53-7008-4cdc-82ed-6900220327ee', 'Cobrar definição e execução da amostragem de casamentos para análise de dados', 'Acompanhar para que o time defina e colete uma amostragem maior de casamentos (por exemplo, ~50 casos) a partir dos documentos consolidados, aceitando que parte será descartada, para ter base estatística suficiente.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'A gente não quer, como pegar grande, uma boa parte, tipo, em vez de 10, 50. Dos 50, a gente não vai ter poréns em 15, tá ligado?', '2026-06-08 13:00:46.344362+00', '2026-06-08 13:00:46.344362+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Isa"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('b226550a-bc4b-46bf-8f84-684673907f13', 'c7896b53-7008-4cdc-82ed-6900220327ee', 'Cobrar uso de IA para extrair e limpar dados dos casamentos consolidados', 'Garantir que, após a consolidação dos materiais, a equipe use IA para resumir e extrair itens contratados, padronizar categorias (fotógrafo/filmmaker etc.) e limpar os dados, organizando-os de forma estruturada.', '?', DEFAULT, NULL, 'quando tiver as planilhas consolidadas', 'media', 'aberta', 'Se ela não consegue juntar todas, todos esses materiais numa pasta, e daí a gente põe a IA para resumir, tá ligado? Para puxar o dado para nós.', '2026-06-08 13:00:46.344362+00', '2026-06-08 13:00:46.344362+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Isa"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('3840627c-8704-4438-bb3f-86a21b56f7e5', '1b43195f-c94a-4df9-ab74-fc61f3260a61', 'Acompanhar entrega do mapeamento de comunicação automática com campos de como, porquê e ideias de solução', 'Vitor pediu para a analista estruturar o problema da comunicação automática: mapear mensagens, registrar como e o que é enviado, explicitar por que cada mensagem existe e propor ideias de solução, para mostrar a ele na segunda/terça. Ele deve cobrar/avaliar esse material se não chegar até lá.', '?', DEFAULT, '2026-06-01 00:00:00+00', 'segunda / terça', 'alta', 'aberta', 'Pode deixar, tá bom, tá bom. Trabalhar nisso então, nesse problema que a gente já tem. Vou colocar o como, o porquê e colocar algumas ideias de solução. E aí eu te mostro segundo, terceiro.', '2026-06-02 17:46:33.690352+00', '2026-06-02 17:46:33.690352+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('ace830dc-1183-42fd-98da-a1e3d4be9e8e', '1b43195f-c94a-4df9-ab74-fc61f3260a61', 'Acompanhar mapeamento de problemas, subproblemas, prioridades e facilidade no projeto de check-in/pontos de contato', 'Vitor definiu o projeto de check-in/pontos de contato como prioridade total e orientou a analista a listar problemas, subproblemas, priorizar por importância e facilidade de resolução. Eles combinaram de revisar isso na terça à tarde, então Vitor precisa cobrar esse mapeamento e fazer a revisão conjunta.', '?', DEFAULT, '2026-06-02 15:00:00+00', 'terça de tarde', 'alta', 'aberta', 'Então eu vou marcar aqui problemas. Subproblemas, que é dentro de cada um, prioridade e facilidade de resolução.
INSERT INTO public.tarefas VALUES ('5c56d0f7-a769-4b4f-b522-0667b9b5727f', '1b43195f-c94a-4df9-ab74-fc61f3260a61', 'Acompanhar criação de visualização no ClickUp para monitorar projetos e alocação de tempo da analista', 'Vitor quer uma página no ClickUp que mostre em que projetos a analista está, quanto tempo dedica a cada um e qual é o próximo da fila, e pediu para ela ver com o Cláudio como criar uma visualização com mais de uma pessoa. Ele deve acompanhar se essa visualização foi configurada e ajustar o formato com ela.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'Ontem comecei a dar uma olhadinha em relação ao ClickUp, que o Cláudio, ele consegue, tipo, se eu peço para ele, ele cria lá. Então eu quero entender com ele que é possível criar lá uma visualização com mais de uma pessoa que estão fazendo coisas diferentes.
INSERT INTO public.tarefas VALUES ('7ac24f05-8a04-4870-abb8-01e131d92cc3', 'eccbdc34-cd1a-4ab8-8607-934a52ae2036', 'Definir processo de acesso à equipe de dados para demandas urgentes', 'Clarificar para Tiago e demais como acessar a equipe de dados (ex.: Isadora) para análises urgentes, definindo canal, critérios de prioridade e fluxo de solicitação, já que hoje isso não está claro para o time.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Como acessamos a equipe de dados é uma pergunta que eu já fiz pro Victor, então é como que a gente disponibiliza esse time pra urgência, ali assim. Então é como é que eu acesso talvez a Isadora pedindo pra ela uma análise XYZ, que eu acho que é importante eu ter. Isso não tá claro pra mim', '2026-05-25 18:31:36.969674+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('4a305e7e-52e7-41ae-a543-7a38eb18101f', '3272f719-ef91-4782-80b1-e1d446c8b817', 'Acompanhar priorização de acompanhamento de viagem e check-in como foco principal da Carla', 'Carla e Vitor alinharam que o principal problema a ser atacado agora é a experiência do cliente em início/fim de viagem, com o check-in como uma das frentes. Vitor deve acompanhar se Carla está de fato priorizando esse tema (acompanhamento + check-in) e não se perdendo em micros ou projetos paralelos como o ''Clube Med''.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Então a senhora no mato, né? ... qual que é a coisa que eu não posso deixar quebrar, principalmente agora, pra mim é começo de viagem... Então check-in, isso aqui, isso aqui. Qual que é o mais importante? Check-in. Então aí o check-in ficou atacado, depois outro.', '2026-05-21 21:55:36.024278+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b822eede-65a7-4baf-b36d-9e920044c1a1', '3272f719-ef91-4782-80b1-e1d446c8b817', 'Alinhar com Isa que ela é apoio de dados para Carla e manter canal aberto para dúvidas técnicas', 'Vitor comentou que já falou com Isa que, embora não possa acompanhá-la diretamente o tempo todo, continuará ajudando na parte técnica de dados e que Isa deve apoiar Carla em tudo que ela precisar de dados. Vitor precisa garantir que Isa entendeu esse papel e que o canal de dúvidas e apoio está funcionando.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'eu não vou largar a mão dela em relação a dados. Tudo que ela tiver de dúvida, como fazer, etc, tipo de analisar, cara, podem chamar ela, continua me chamando. E você é a pessoa do restante, tá ligado?', '2026-05-21 21:55:36.024278+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('bc7c7dba-0347-47f4-b0c9-1705c7c4e775', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Cobrar da Ana proposta de mensagens e fluxo automático para convidados', 'Vitor pediu para a Ana entender o que é necessário para ter mensagens de fluxo automático para convidados, levantar como isso poderia ser automático e trazer uma proposta para ele discutir e construir.', 'Ana', DEFAULT, NULL, NULL, 'alta', 'concluida', 'Ana, a gente precisa ter mensagem de fluxo automático. Entenda, vê o que é e me traz a proposta. Eu não vou fazer mais nada. Faz lá, vamos conversar, é assim, assim, assim.', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', '2026-05-25 23:42:21.165161+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'aguardar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f045b07a-af9d-4d6d-bd3d-c53ce7190997', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Definir o escopo do projeto de convidados e iniciar busca de candidatos por indicação', 'Vitor se comprometeu a definir o escopo do projeto para a área de convidados e já começar a pensar e chamar algumas pessoas/indicações para a vaga de responsável por essa área.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Então vou definir o escopo e já vou pensar, já vou até chamar algumas pessoas, já. Porque eu vou dar uma olhada e pensar nisso, como você tá, o que tem, conhece alguém pra ir mapeando.', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('ad6c9de6-0551-4c3c-a526-18ab7a86e170', 'eccbdc34-cd1a-4ab8-8607-934a52ae2036', 'Definir política de uso e liberação de GPT Cloud e contas corporativas de IA', 'Estruturar regras claras para liberação de acesso ao GPT Cloud/contas corporativas (quem pode liberar, critérios, limites de custo por assinatura, uso individual vs. compartilhado) e comunicar ao time, evitando liberações ad hoc e risco de dados sensíveis.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'me preocupo com o que a gente tem, a conta corporativa do GPT e tem no Cloud... dá pra liberar os dois, só que o problema é que cada assinatura individual é mais cem pila... e a gente tá liberando assim sem... / Não, eu tô segurando mais ou menos. Eu não tô liberando pra todo mundo. Eu tô liberando. / a gente tá sem uma... uma regra.', '2026-05-25 18:31:36.969674+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('0be62be1-9c25-4238-b0bd-2378abb4614c', '30286fa4-1a4b-46e1-8f1b-33824febeb3f', 'Escrever o básico da vaga de responsável por convidados e enviar até sexta', 'Vitor combinou de escrever o básico da descrição da vaga para a área de convidados e enviar até sexta para os outros revisarem, antes da reunião de alinhamento na terça.', 'Diana', DEFAULT, NULL, 'até sexta', 'alta', 'concluida', 'Então a gente deixa a reunião para segunda e eu mando até sexta, ok? isso, isso. Tá, põe, na verdade, acho que é melhor, vamos fazer predicionado, põe na terça.', '2026-05-20 15:08:39.694608+00', '2026-05-25 23:42:44.883927+00', '2026-05-25 23:42:28.064143+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'aguardar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('49c8ae55-96e6-46b5-b165-f1290c954764', '0ae61937-3876-46a6-a1ef-b9984696747c', 'Levantar números de conversas iniciadas, encerradas e respondidas', 'Obter os dados de quantas conversas começaram, quantas terminaram e quantas foram respondidas para ter o dado consolidado corretamente.', 'vitor', DEFAULT, NULL, NULL, 'media', 'concluida', 'a gente precisa puxar esse número de quantas conversas começaram, quantas terminaram, quantas foram respondidas, etc, para saber certinho o dado', '2026-05-19 13:40:59.122107+00', '2026-05-25 23:42:44.883927+00', '2026-05-21 22:34:33.002011+00', NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('03210d1e-692c-45ab-a19a-356c0376c34a', 'f8c50470-5ad5-4db5-94bb-01484d364fcf', 'Concluir análise de dados de Trips até amanhã', 'Finalizar até amanhã o relatório/análise de Trips cruzando o que os noivos declararam (valor, convidados, destino) com o que de fato fecharam, para chegar na reunião sem dúvidas sobre os dados.', 'vitor', DEFAULT, '2026-05-28 00:00:00+00', 'até amanhã', 'alta', 'aberta', 'eu faço de trips até amanhã… eu tô debruçado nisso para amanhã a gente vir falar: não temos dúvida dos dados', '2026-05-27 19:02:07.799431+00', '2026-05-27 19:02:07.799431+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('62d813eb-ebcb-462e-af51-9a452bdd0736', 'f8c50470-5ad5-4db5-94bb-01484d364fcf', 'Linkar depois os dados de Trips com o relatório financeiro de casamentos', 'Após terminar a análise atual, conectar os dados que Vitor está montando (número de venda do Monde, telefone, código do casamento) com o relatório financeiro de casamentos do interlocutor para ter uma visão macro de qualidade dos casamentos.', 'vitor', DEFAULT, NULL, 'depois que terminar essa aqui', 'media', 'aberta', 'Aí depois, quando terminar essa aqui, eu ponho para linkar com o seu e a gente olhar uma visão mais macro de qualidade dos casamentos mesmo', '2026-05-27 19:02:07.799431+00', '2026-05-27 19:02:07.799431+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('52d5dd67-72f9-48e6-bfa5-46e2fe9ecb6b', 'f8c50470-5ad5-4db5-94bb-01484d364fcf', 'Cobrar conversa prévia do interlocutor com Marcelo sobre o dash e os números', 'Garantir que o interlocutor converse com o Marcelo antes da reunião, alinhando minimamente por que o número do dash atual está errado e preparando Marcelo para a nova visão de dados.', '?', DEFAULT, '2026-05-28 00:00:00+00', 'antes da reunião de amanhã', 'alta', 'aberta', 'Eu quero ainda que você troque essa ideia prévia com o Marcelo para não chegar desavisado na reunião, que é minimamente, cara, você e ele saberem por que que tá errado o número do Dash', '2026-05-27 19:02:07.799431+00', '2026-05-27 19:02:07.799431+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3823ddaa-83ce-4637-b7c9-e6f6bd3ed0f5', 'f8c50470-5ad5-4db5-94bb-01484d364fcf', 'Acompanhar fluxo manual de cadastro de leads de extras no CRM pela Estela', 'Vitor definiu que, enquanto a automação não estiver pronta, quando o convidado responder sobre extras alguém deve colocar Estela no fluxo e ela deve cadastrar o lead no CRM para as meninas; acompanhar se esse fluxo manual está acontecendo.', '?', DEFAULT, NULL, 'enquanto a automação não estiver pronta', 'media', 'aberta', 'nem que por enquanto a gente faça manual… a pessoa falou, põe a Estela no fluxo. Não, Estela, quem falar você cadastra no CRM ali para as meninas', '2026-05-27 19:02:07.799431+00', '2026-05-27 19:02:07.799431+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('2c9de67f-f8a2-4eec-9452-8805c281c3a2', '3272f719-ef91-4782-80b1-e1d446c8b817', 'Garantir que Carla acione Isa para ajudar no mapeamento de acompanhamento de viagem/check-in', 'Vitor orienta que, para o problema de acompanhamento de viagem e check-in, Carla pode e deve pedir ajuda da Isa (apoio de dados) para pensar alternativas técnicas e mapeamento. Vitor deve cobrar/confirmar se Carla está de fato envolvendo Isa nesse trabalho.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'ou você vai pedir para alguém fazer isso para você a isa alguém cara quais são as alternativas porque se já tem um problema né o que eu preciso agora que a primeira coisa atacar check-ins', '2026-05-21 21:55:36.024278+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('29c577e8-226b-4d67-bfc1-b2ee28cf6c89', '3272f719-ef91-4782-80b1-e1d446c8b817', 'Acompanhar adoção do ClickUp por Isa e Carla para organizar demandas de dados e desenvolvimento', 'Vitor disse que já pediu para Isa usar o ClickUp e que Carla também deve começar a usar para registrar tarefas e roadmap, especialmente para Isa e Matheus. Vitor precisa conferir se Isa e Carla estão usando o ClickUp para listar o que estão fazendo e as demandas em fila.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'aí já falei pra ela fazer um negócio que é no click up, aí você começa a usar também. Que a gente consegue pôr as tarefas tudo bonitinho, né. Que é importantíssimo que ela e o Matheus, que todo mundo pede coisa pro Matheus, tenham lá o que que eles tão fazendo', '2026-05-21 21:55:36.024278+00', '2026-05-25 23:42:44.883927+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('e51d4686-ee82-40cd-9ee7-6dd89b36b520', '9f3e04e6-65f4-49b8-b948-d39ce6813d14', 'Garantir uso correto do Score pelas SDRs e ajustar eventuais problemas', 'Validar com Vanessa, Sara e demais SDRs se o Score está sendo efetivamente usado, conferir os dados gerados e, se houver algo errado, ajustar a configuração para eliminar casos de não uso.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Vitor: "Eu preciso validar com o que elas estão usando... Mas eu não fui atrás do dado, olhar direitinho. Põe aí até, Marcelo, como é minha tarefa de eu garantir que tá usando, tá tudo certo. Se tem alguma coisa errada, ajusta e vai. Não é pra ter não uso."', '2026-05-25 23:43:55.100926+00', '2026-05-25 23:43:55.100926+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('1836c58b-f3e3-4937-abaf-af29a6a176ed', '9f3e04e6-65f4-49b8-b948-d39ce6813d14', 'Entregar Analytics do Trips integrando dados do Active e CRM', 'Construir o analytics de Trips usando a API do Active já linkada ao CRM, mapeando conversão de taxa, próximos passos e resultados, e apresentar esse painel na reunião da próxima quinta-feira (28/05).', 'vitor', DEFAULT, '2026-05-28 00:00:00+00', 'quinta-feira que vem, dia 28', 'alta', 'aberta', 'Vitor: "Coloca, cara, de verdade, esse é um negócio que se eu fizer meia hora eu vou conseguir ter essa informação... Pode pôr pra mim, pra semana que vem vai estar na entrega." Marcelo: "Semana que vem é quinta-feira que vem?... 28."', '2026-05-25 23:43:55.100926+00', '2026-05-25 23:43:55.100926+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d9624c10-ee4c-4bad-9c7c-fdf7d8db537e', '12a6c235-6cd8-42f9-8a21-ac6a4da140ef', 'Cobrar levantamento de problemas e pontos de melhoria nas reuniões de casamentos', 'Vitor pediu para o time (Mariana e demais) pensar e levantar os problemas recorrentes nas reuniões de casamentos (itens que voltam, dúvidas sobre o que já está feito, informações que poderiam estar em sistema/planilha) para ajudar no material que a Ana está juntando. Acompanhar se esse levantamento está sendo feito e se está chegando para a Ana.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'o que eu queria pedir, um favor, se vocês já conseguissem pensar, tipo isso que você falou, Mari, a gente faz a reunião, fala de casamento, casamento, depois volta. E aí fica, eu não sei quem já tem tal coisa, quem tem aquilo, tipo, levantar meio que os problemas que vocês identificam para inclusive ajudar nessa, nesse negócio que a Ana tá juntando tudo', '2026-05-26 17:43:17.695276+00', '2026-05-26 17:43:17.695276+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('958e5e93-0697-4044-987c-e2f348c43903', 'a0805a28-31ba-4d30-b67b-bece7b8457dc', 'Acompanhar montagem da planilha consolidada de convidados e extras por casamento', 'Vitor combinou com alguém da equipe que será montada uma planilha única com cada pessoa, casamento, datas/período de viagem, se vai estender, o que já comprou e quando libera, para definir ofertas de extras e mensagens segmentadas. Ele deve acompanhar se essa planilha está sendo criada conforme combinado.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'E aí eu acho que o resultado final disso precisa ser essa, é como se fosse uma planilha só que tem a pessoa e tem todas essas informações. ... Não, já monta a planilha para tudo, e aí a gente decide para quem vai disparar. ... Ok, vou fazer isso então.', '2026-06-02 17:48:22.029889+00', '2026-06-02 17:48:22.029889+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('04a7d095-5de0-4b55-acd3-c9fc279bb327', 'a0805a28-31ba-4d30-b67b-bece7b8457dc', 'Cobrar envio das programações de casamento pelas meninas de produção', 'Vitor planeja pedir para as meninas de produção enviarem as programações dos casamentos, especialmente quando não estão no admin, para cruzar com períodos de bloqueio e definir quando é seguro vender passeios. Ele precisa efetivamente fazer esse pedido e acompanhar o retorno.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'o que em tese dá mais trabalho, que daí também é só pedir para o Cláudio fazer, é que eu peço para as meninas de produção me mandarem, me mandarem as programações.', '2026-06-02 17:48:22.029889+00', '2026-06-02 17:48:22.029889+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('11012348-3dc8-47b5-a8da-f8bed0d8c8d5', 'a0805a28-31ba-4d30-b67b-bece7b8457dc', 'Acompanhar inclusão das mensagens de disparo no Antico', 'Vitor alinhou que, após terminar a montagem da planilha, a pessoa da equipe vai colocar todas as mensagens de disparo no Antico. Ele deve conferir depois se essas mensagens foram efetivamente cadastradas.', '?', DEFAULT, NULL, 'depois que terminar a planilha', 'media', 'aberta', 'E aí eu já vou colocando no— depois quando eu terminar isso daqui, eu vou colocando todas as mensagens lá no As mensagens que a gente envia do Antico.', '2026-06-02 17:48:22.029889+00', '2026-06-02 17:48:22.029889+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('7536c555-5f1c-4beb-b627-42db029f3776', 'a0805a28-31ba-4d30-b67b-bece7b8457dc', 'Retomar projeto grande de automação do fluxo após concluir o projeto de extras', 'Vitor combinou que, depois de liberar este projeto de disparo de extras, a pessoa da equipe voltará a olhar o fluxo grande, mostrando onde aperta botão e como funciona, para automatizar o processo como um todo. Ele precisa lembrar de puxar essa retomada quando o projeto atual estiver concluído.', 'vitor', DEFAULT, NULL, 'depois de liberar esse projeto', 'media', 'aberta', 'então a gente tá fazendo esse projeto, aquele, o que você tá fazendo grandão, tá meio que pausado. Quando a gente liberar esse, você volta para olhar o fluxo, mesmo que mostrar lá que a gente aperta botão, aonde é, etc., para a gente conseguir automatizar esse processo como um todo.', '2026-06-02 17:48:22.029889+00', '2026-06-02 17:48:22.029889+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d8e70cd7-d289-45f3-a0b8-2c3a252209bc', '0bc856aa-6474-4d18-a82a-3d04071728f9', 'Finalizar e refinar visões de funil e qualidade de lead para reunião de amanhã', 'Concluir até amanhã de manhã as visões/dashboards que comparam período todo vs últimos 90 dias, incluindo ajustes nos números que ainda não estão certos, visão da closer (tirando o efeito das reuniões ''nada a ver'' que o Marcelo teria filtrado) e análises de faixa de investimento e score/qualidade do lead, para usar no papo de amanhã.', 'vitor', DEFAULT, '2026-06-02 09:00:00+00', 'amanhã de manhã', 'alta', 'aberta', 'tô correndo para tentar para amanhã de manhã, mas eu vou precisar estar tipo isso que você falou do que a closer, tem que estar com certeza absoluta, velho', '2026-06-08 00:21:10.799018+00', '2026-06-08 00:21:10.799018+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Tiago", "Marcelo"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('0cd8285d-ed3d-4769-8403-bbda6d4660c9', '0bc856aa-6474-4d18-a82a-3d04071728f9', 'Preparar pauta e perguntas para Tiago alinhar com Marcelo sobre remarketing e materiais ricos', 'Estruturar, antes da conversa do Tiago com o Marcelo, quais pontos ele deve pedir: visão clara do que é feito hoje de remarketing (mídia e acompanhamento de leads que não converteram), resultados atuais, e quais materiais ricos existem para vendas encantar leads; ajudar Tiago a abordar o tema sem soar como acusação e com foco em clareza e plano de melhoria.', 'vitor', DEFAULT, '2026-06-01 18:00:00+00', 'hoje, antes da conversa do Tiago com o Marcelo', 'alta', 'aberta', 'em quanto tempo o Marcelo consegue mostrar para gente o que ele tá fazendo em, nessa parte de [...] remarketing [...] cara, você consegue entregar amanhã de manhã essa visão do que que você faz [...] Porque aí ele vai olhar, isso já vai fazer com que ele veja que ou tá bom ou não tá', '2026-06-08 00:21:10.799018+00', '2026-06-08 00:21:10.799018+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '4100263a-e4cb-4a7f-a741-44666728339e', NULL, '["Tiago", "Marcelo"]', 'Marketing');
INSERT INTO public.tarefas VALUES ('ee7cc8b2-3c06-440e-af05-de166ef31cb6', '0bc856aa-6474-4d18-a82a-3d04071728f9', 'Ajustar tratamento dos dados da closer considerando filtros do Marcelo', 'Revisar no modelo/relatório como as reuniões ''nada a ver'' que eram passadas para a closer estão sendo tratadas, garantindo que o efeito que o Marcelo disse ter tirado (não contar como reunião realizada da closer) esteja corretamente refletido nos dados para não distorcer a conversão dela.', 'vitor', DEFAULT, '2026-06-02 09:00:00+00', 'até amanhã de manhã, junto com as visões', 'alta', 'aberta', 'o Marcelo diz que [...] ele é como se fosse perdido, ele não conta como realização, é união realizada da close, para não ferrar o número, mas ela faz. Eu vou entender aqui Isso tem que ser muito claro, se tira o peso disso mesmo ou não, né?
INSERT INTO public.tarefas VALUES ('57717c57-b83b-4a29-bde7-f596ef9c5303', '964b0d9a-3288-46dc-95e3-a4110ebce1bf', 'Cobrar ajuste do arquivo de importação de vendas multi e entendimento do erro', 'Vitor pediu para o interlocutor técnico garantir que o arquivo de vendas multi esteja exatamente no mesmo modelo (nomes de colunas) do último upload bem-sucedido e tentar novamente a importação, além de entender por que 476 registros foram importados sem atualizar cards. Se não funcionar, ele quer que seja perguntado ao amigo/Claudinho. Vitor precisa acompanhar e cobrar até que a importação atualize corretamente os cards.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Talvez era, mano, você subiu venda por produto, o relatório? ... Eu queria que fosse só você garantir que tá no modelo que você subiu o último, sabe? ... Não dá para perguntar para o teu amigo? Dá, vou perguntar. Deixa eu perguntar para o Claudinho.', '2026-05-26 21:23:25.522101+00', '2026-05-26 21:23:25.522101+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('31c9dd5c-c1ba-4b87-9718-936a90052aaa', '964b0d9a-3288-46dc-95e3-a4110ebce1bf', 'Perguntar ao Claudinho sobre o problema na importação de vendas multi', 'Vitor se comprometeu a falar com o Claudinho para entender por que o arquivo de vendas multi não está atualizando os cards (476 registros importados, zero cards atualizados) e obter orientação sobre o erro no modelo ou no processamento.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Não dá para perguntar para o teu amigo? Dá, vou perguntar. Deixa eu perguntar para o Claudinho. Segura aí.', '2026-05-26 21:23:25.522101+00', '2026-05-26 21:23:25.522101+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f5741ce9-314c-4a95-88e8-82f505a7b132', '964b0d9a-3288-46dc-95e3-a4110ebce1bf', 'Explorar alternativa de arquitetura para o app de áudios e tarefas em nuvem', 'Vitor comentou que hoje o app de áudios roda no computador dele via iCloud e que, para outras pessoas usarem, precisaria virar desenvolvedor Apple e publicar um app em nuvem. Ele se comprometeu a "ver essa possibilidade" de usar outro iCloud/dispositivo ou arquitetura que permita rodar sem depender do computador dele ligado.', 'vitor', DEFAULT, NULL, 'ver essa possibilidade', 'media', 'aberta', 'Então eu preciso fazer um aplicativo para poder ser em nuvem. ... Tá, vou ver essa possibilidade. Que eu fiquei apanhando para tentar fazer no meio e tal, aí não integrar.', '2026-05-26 21:23:25.522101+00', '2026-05-26 21:23:25.522101+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('03e47115-ba20-45e5-b686-ecba9ae52e5b', '0f5da971-4fc5-4e0e-8740-90bc0330286b', 'Conversar hoje com o time sobre conversão baixa e processo atual', 'Hoje Vitor pretende reunir as meninas envolvidas (planejamento/pós-venda) para expor a situação da conversão (3% em vez de 100%), entender o processo atual passo a passo e alinhar que essa área é uma extensão de vendas.', 'vitor', DEFAULT, NULL, 'hoje', 'alta', 'aberta', 'Cara... Hoje eu vou trocar ideia com elas... Eu quero expor exatamente o que tá acontecendo com a conversão desses... Hoje a gente tem 3% da prova... Deveria ser 100... Eu preciso que esse número reaja...', '2026-06-02 18:20:56.717776+00', '2026-06-02 18:20:56.717776+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f62c6dbd-7e20-4aa7-a4d1-5415cf9b680c', '0c01ac94-81b1-4cb9-887b-e8bfea1656c4', 'Acompanhar mapeamento detalhado do fluxo de mensagens e extras feito pela Ana', 'Vitor pediu para a Ana destrinchar o problema e mapear em detalhe o fluxo atual de mensagens para convidados (da compra de hospedagem até extras), incluindo o que causa cada problema e como o processo funciona hoje, como próxima etapa do trabalho. Acompanhar esse mapeamento e cobrar se ela não avançar ou não compartilhar o resultado.', 'Ana', DEFAULT, NULL, NULL, 'media', 'aberta', 'Vitor: "Eu acho que aí essa já pode ser a próxima etapa, que é você destrinchar, já vai te ajudar muito a pensar como resolver, tá?"', '2026-05-27 20:00:58.911526+00', '2026-05-27 20:00:58.911526+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b016655f-8b9a-4d4a-89c0-0f3455a3767c', '0f5da971-4fc5-4e0e-8740-90bc0330286b', 'Definir e conduzir alinhamento com pós-venda sobre como deve funcionar', 'Vitor planeja juntar algumas pessoas e fazer um alinhamento específico para o pós-venda, explicando como ele precisa que o processo funcione e co-construindo com elas o ''como vamos fazer''.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Tipo eu vou falar... Vamos juntar umas duas... Falaram... Então aqui para o pós-venda... Eu preciso que seja assim... Essa assim... Como é que vamos fazer... Entendeu?', '2026-06-02 18:20:56.717776+00', '2026-06-02 18:20:56.717776+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f85994f8-842b-4758-8d94-045111b30408', '0f5da971-4fc5-4e0e-8740-90bc0330286b', 'Preparar e conduzir sessão de liderança com vídeo para o time', 'Vitor quer usar um vídeo/podcast sobre liderança amanhã como base para uma sessão em que ele fala sobre liderança, assiste o vídeo com o time (ou pede que assistam antes) e conduz discussão com exemplos reais.', 'vitor', DEFAULT, NULL, 'amanhã', 'alta', 'aberta', 'Eu queria que fosse feito amanhã... Se você achar que vale... eu ia propor que ou você... ou a gente ia falar para... fazer o... é o podcast... Você assiste um vídeo... O vídeo é bom... E aí seria um início... ... Amanhã vai ser... O Victor é atração... Liderança ele vai falar... Sobre as coisas e tal... E eu vou... 17 minutos... Dá pra gente assistir junto e trocar ideia...', '2026-06-02 18:20:56.717776+00', '2026-06-02 18:20:56.717776+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('89c37380-8ce4-4608-a60b-44f4a7694452', 'a728cddd-8e1d-4944-9c82-41d3374ad341', 'Alinhar com Thiago plano de compra das noites extras por fora para o casal do Paradisos', 'Conversar com o Thiago ainda hoje ou amanhã de manhã para explicar o caso do casal Paradisos, entender como a empresa pode comprar as noites extras (18 a 24) por fora com menor risco e definir o procedimento operacional caso o hotel não responda.', 'vitor', DEFAULT, NULL, 'até amanhã de manhã', 'alta', 'aberta', 'Vitor: "Então eu acho que é só ver como que é o melhor jeito de comprar isso. O que o Thiago acha? Se espera até amanhã de manhã, talvez. Eu não esperaria muito tempo para a gente tomar ação"', '2026-06-03 11:42:16.786676+00', '2026-06-03 11:42:16.786676+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('a61871d0-9393-4598-8754-fe2e18cb6bc3', 'a728cddd-8e1d-4944-9c82-41d3374ad341', 'Definir com Thiago e Estela se haverá compra imediata das noites extras para garantir os quartos', 'Com base na conversa com Thiago, decidir se a empresa já compra as noites extras para garantir os quartos do casal, assumindo que os noivos pagam igual para igual, e estruturar o fluxo de reembolso/ajuste caso o hotel depois confirme o bloqueio normal.', 'vitor', DEFAULT, NULL, 'após retorno do hotel amanhã', 'alta', 'aberta', 'Vitor: "eu fecharia do nosso lado para eles e eles pagariam para gente esses a mais para a gente garantir que a gente conseguiu fechar. Quando o hotel responder..."', '2026-06-03 11:42:16.786676+00', '2026-06-03 11:42:16.786676+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f36b8a03-e246-4eb4-98d1-314835d7b61d', 'a728cddd-8e1d-4944-9c82-41d3374ad341', 'Garantir que Estela agende reunião com Thiago para a tarde de amanhã sobre o caso Paradisos', 'Acompanhar se Estela realmente deixou agendada uma reunião com o Thiago para amanhã à tarde para discutir o caso do casal Paradisos e o plano de ação, cobrando se necessário.', 'Estela', DEFAULT, NULL, 'amanhã à tarde', 'media', 'aberta', 'Estela: "eu vou deixar uma reunião com o Thiago agendada para de tarde então." Vitor: "Isso, já deixa marcado. Eu já chamei ele aqui."', '2026-06-03 11:42:16.786676+00', '2026-06-03 11:42:16.786676+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('80851da7-bb37-4124-95c6-06ab095f2db4', 'a728cddd-8e1d-4944-9c82-41d3374ad341', 'Escalar problema com o hotel Paradisos para contato sênior após definir plano com Thiago', 'Depois de alinhar com Thiago, orientar ou apoiar a escalada do caso para alguém importante no hotel Paradisos (por meio da correspondente ou outro contato) deixando claro o impacto na empresa e exigindo respostas mais rápidas para as próximas demandas.', 'vitor', DEFAULT, NULL, 'após conversa com Thiago e retorno do hotel amanhã', 'media', 'aberta', 'Vitor: "eu tentaria falar, tipo, mano, escalar isso para falar com alguém bem importante lá no hotel, sabe? O Thiago tentar falar alguém para a gente falar: cara, vocês estão ferrando nós"', '2026-06-03 11:42:16.786676+00', '2026-06-03 11:42:16.786676+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3d10f530-ee2a-4fcf-b794-e5a5752388ca', 'a728cddd-8e1d-4944-9c82-41d3374ad341', 'Revisar situação do casal Paradisos amanhã e decidir se age antes ou depois do retorno prometido pelo hotel', 'No início de amanhã, checar se houve resposta do hotel Paradisos, decidir se espera até o prazo prometido pela correspondente (amanhã) ou se já aciona o plano de compra por fora e escalada, garantindo que o problema do casal seja resolvido rapidamente.', 'vitor', DEFAULT, NULL, 'amanhã', 'alta', 'aberta', 'Vitor: "Mas beleza, então não teria problema de esperar até eu não deixaria passar de amanhã, já que a mulher falou que responderia amanhã, sabe?"', '2026-06-03 11:42:16.786676+00', '2026-06-03 11:42:16.786676+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('579cd2d2-ae15-46c5-9d53-8aa45dbe5f6f', '0bc856aa-6474-4d18-a82a-3d04071728f9', 'Validar e ajustar filtros das visões de faixa de investimento e evolução do ticket', 'Rever os filtros das visões que comparam o valor que o lead declarou inicialmente com o valor efetivo após planejamento, garantindo que a análise de mudança de faixa (ex.: até 50k que vira 100k) esteja correta e utilizável para decidir quais leads não descartar.', 'vitor', DEFAULT, '2026-06-02 09:00:00+00', 'até amanhã de manhã', 'media', 'aberta', 'eu tenho que, eu tenho que mudar os filtros aqui. Eu depois eu te mostro para não você ficar confuso. Mas aí eu vou olhar para tipo dos leads que tem esse, o ideal, eu acho que ele tá num bom filtro.', '2026-06-08 00:21:10.799018+00', '2026-06-08 00:21:10.799018+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Tiago"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('030252e9-ab76-417c-b325-7735dd618447', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Ajustar análise de leads duplicados no funil de Weddings', 'Victor precisa entender e tratar o volume de leads duplicados no funil de Weddings para não distorcer as taxas de conversão, integrando isso ao dash que está construindo.', 'vitor', DEFAULT, NULL, 'até terça de manhã ou quarta (junto com analytics de Weddings)', 'alta', 'aberta', 'parece que tem um volume de leads duplicados que eu preciso entender... se eu tenho 20% de leads duplicados... eu tô ferrando a minha análise de conversão.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('e13d0a9f-323d-4ab1-af68-d1ab17670f80', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Realizar reunião de acompanhamento sobre leads e decisões de marketing na quarta à tarde', 'Victor combinou com o grupo de marcar uma reunião na quarta à tarde para revisar o andamento e próximos passos em relação às decisões sobre leads tomadas na terça.', 'vitor', DEFAULT, NULL, 'quarta-tarde', 'alta', 'aberta', 'vocês acham que a gente pode deixar marcado para quarta-tarde a gente sentar para ver o andamento ou minimamente os próximos passos em relação ao que a gente decidiu na terça?', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('cd9692ae-2dc2-4134-aa81-0a98b3d180cf', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Vanessa sobre extração das transcrições do Elephant', 'Victor pediu para Vanessa falar com o pessoal do Elephant para baixar todas as transcrições e ainda não cobrou o retorno; precisa acompanhar para poder rodar análises retroativas de score.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Eu pedi para Vanessa falar com o pessoal do Elephant para a gente baixar todas as transcrições... Só que eu não cobrei a Vanessa ainda do retorno, do se ela conseguiu isso.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b2dbe132-7535-4148-be93-efed1e70a9be', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar entrega do relatório de acompanhamento de CRM pela Fernanda', 'Marcelo disse que vai organizar com a Fernanda um relatório de acompanhamento do CRM e próximos passos; Victor deve acompanhar se esse relatório é produzido e usado nas próximas reuniões.', 'vitor', DEFAULT, NULL, 'semana que vem (implícito)', 'media', 'aberta', 'Aí eu vou organizar com a Fernanda um relatório para a gente poder ter de acompanhamento e dos próximos passos.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('90e7af55-e24a-423c-93f9-3a122fbc6bb8', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Isa sobre mapeamento e consolidação de dados de casamento', 'Marcelo sugeriu uma rodada para mapear todos os dados gerados/duplicados (Vitor, Ian, Isa, Rafa mexendo em dados de casamento). Victor concordou que é montar a base de dados; precisa cobrar Isa quando houver respiro para liderar esse projeto.', 'vitor', DEFAULT, NULL, 'quando sair do ''fundo do mar'' de dados atuais', 'baixa', 'aberta', 'Será que a gente não tem que fazer uma rodada em que a gente mapeia todos esses dados...?
INSERT INTO public.tarefas VALUES ('6a4e21e0-8e32-44da-afc1-caf155668bda', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Garantir que Isa valide e comece a usar o novo site de planilha de convidados', 'Victor já arrumou o site que gera a planilha de convidados e precisa que as meninas de planejamento validem e passem a usar, eliminando trabalho manual de conversão de planilhas.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'essa do meio aí, do ajuste da planilha da Ju, eu arrumei, né? Só precisa as meninas validar e começar a usar, que é o site lá que— que é isso, é exatamente isso, não é?', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3d30dc3f-6493-44a4-be33-d5e1b0fe71b0', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Isa sobre estudo dos 600 convidados extras e plano de contato', 'Thiago pediu para Isa verificar se já foi tirada a lista de 600 pessoas extras e começar a trabalhar para chamá-las; Victor orientou fazer um estudo paralelo e possivelmente disparar comunicação para todos. Ele deve acompanhar esse avanço.', 'vitor', DEFAULT, NULL, 'mostrar segunda ou terça', 'alta', 'aberta', 'Thiago tava conversando comigo hoje de manhã e ele falou que ele queria pegar se a gente já tinha tirado aquela lista de 600 pessoas e se a gente já tinha começado a trabalhar para chamar essas pessoas extras.
INSERT INTO public.tarefas VALUES ('ddbbb7b9-9bf4-48c1-aae1-43463c324c65', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Revisar com Isa o mapeamento da jornada de convidados e fluxos de comunicação', 'Isa está mapeando a jornada do convidado, problemas e mensagens; Victor combinou de revisar o material na segunda às 13h30 para ajudar a priorizar soluções e automações.', 'vitor', DEFAULT, NULL, 'segunda, 1:30', 'alta', 'aberta', 'Segunda eu marco 1:30 de volta, acho que ele antes.
INSERT INTO public.tarefas VALUES ('d2662da1-1bc5-484f-92b5-8fc296a21093', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar Isa no projeto de pontos de contato importantes com o cliente (check-in)', 'Victor orientou Isa a tratar o projeto de check-in como ''pontos de contato importantes com cliente'', mapear problemas, subproblemas, prioridades e facilidades, e combinou de acompanhar a construção e discutir na terça à tarde.', 'vitor', DEFAULT, NULL, 'terça de tarde', 'alta', 'aberta', 'eu não chamaria de check-in, eu chamaria um projeto de pontos de contato importante com cliente... Então esse projeto é bem importante.
INSERT INTO public.tarefas VALUES ('fe329b4c-503a-41e6-8100-5e368f4f684d', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Orientar Isa na criação de visão no ClickUp para acompanhamento de projetos e carga', 'Victor pediu para Isa estruturar no ClickUp uma visualização que mostre em que projetos ela está, quanto tempo dedica a cada um e o próximo da fila, para que ele e Thiago possam acompanhar prioridades e carga.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'outra coisa é o negócio do ClickUp, que aí esse eu, aquele negócio que eu te falei, uma página só que eu conseguisse saber o que tá acontecendo, tal, para conseguir ajudar a entender tempos, o que passaram...', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('1d0b52a7-fb76-4bea-abb1-5e72f7bc67f6', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Reunião com Fernanda na terça à tarde sobre projeto de check-in e mapeamento de problemas', 'Victor combinou com Fernanda de falar na terça à tarde para revisar o mapeamento de problemas, subproblemas e possíveis soluções do fluxo de check-in/pontos de contato.', 'vitor', DEFAULT, NULL, 'terça de tarde', 'alta', 'aberta', 'E aí na terça a gente fala melhor, tá bom?
INSERT INTO public.tarefas VALUES ('c7ea1bb9-32a5-4b70-b66f-73ca35c25400', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Fernanda pelo mapeamento de problemas, subproblemas e prioridades do fluxo de check-in', 'Victor orientou Fernanda a mapear problemas, subproblemas, prioridades e facilidade de resolução no processo de check-in/pontos de contato, para discutir na terça; ele deve cobrar esse material se não chegar.', 'vitor', DEFAULT, NULL, 'até terça de tarde', 'alta', 'aberta', 'A primeira parte aqui é: você já mapeou os problemas, é ter eles claros e mapear os subproblemas e aí setar prioridades... aí na terça a gente fala melhor.', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('019556c2-52d6-42fd-b269-b7a9b91eade8', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Speaker F pelo mapeamento de problemas e subproblemas do check-in', 'Verificar se Speaker F conseguiu mapear problemas, subproblemas, prioridades e facilidade de resolução no fluxo de check-in/pontos de contato antes da reunião de terça.', 'vitor', DEFAULT, NULL, 'até terça de tarde', 'alta', 'aberta', 'Mas aí você vai ver se você já vai ter conseguido fazer esse mapeamento dos problemas, subproblemas, e como que você arrumaria cada um deles.', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c6a9dc9c-5995-4685-bb1e-74bd2621d8c3', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Definir junto com Fernanda o plano de implementação no CRM para o novo fluxo de check-in', 'Após Fernanda mapear problemas e soluções, Victor precisa ajudá-la a definir como implementar no CRM (uso de dados do Monde, campos, alertas, etc.), incluindo se ela terá acesso/apoio de Matheus e Victor.', 'vitor', DEFAULT, NULL, 'após definição do plano (sem data específica)', 'media', 'aberta', 'parte depois que você tem o plano definido... Aí você fala assim, cara, eu tenho isso, é muito importante "Isso é fácil para mim?" É. "Consigo ajuda?"... E me parece de fato que a gente já tem muita coisa construída para resolver esse problema...', '2026-06-01 16:49:42.828822+00', '2026-06-01 16:49:42.828822+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('6e4dfda9-8884-40dd-ac1d-986cea5ed1d1', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Finalizar dashboard de Trips até terça', 'Concluir o dashboard de Trips, validar se os dados estão corretos e deixá-lo pronto para apresentação na próxima terça-feira.', 'vitor', DEFAULT, NULL, 'terça', 'alta', 'aberta', 'Eu tinha que terminar o Dash de trips, que eu não avaliei se tá correto ainda, então eu não vou entregar', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('0eb50fa8-1a1c-47f9-baf5-4c980eb5769f', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Finalizar analytics de Weddings com análise de contratos até terça/quarta', 'Concluir o analytics de Weddings, incluindo o estudo dos contratos que fecharam (índice da mentira: valor declarado vs. real e número de convidados) e entregar até terça de manhã ou quarta.', 'vitor', DEFAULT, NULL, 'até terça de manhã ou quarta', 'alta', 'aberta', 'esse tá até terça de manhã ou quarta, né, que é o prazo para eu terminar o analytics de weddings dessa parte, vai estar lá', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('5c337cf4-5045-4009-9c9d-45a344a718df', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Vanessa sobre download das transcrições do Elephant', 'Verificar com a Vanessa se ela já falou com o pessoal do Elephant e conseguiu baixar todas as transcrições, para poder rodar análise retroativa e ajustar o score no Elephant.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Eu pedi para Vanessa falar com o pessoal do Elephant para a gente baixar todas as transcrições... Só que eu não cobrei a Vanessa ainda do retorno', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('cb69759c-56cc-4405-b0b2-8b6232cf6a46', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Rodar análise retroativa de score usando dados do Elephant', 'Após obter as transcrições do Elephant, rodar o score retroativo para entender o comportamento histórico dos leads e alinhar o score do Elephant com o modelo atual.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'se baixar todas, eu consigo rodar aqui para ele fazer retroativo. E aí a gente ajustar o elefante para ele ter o score parecido', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('2c9eb855-dc63-48d0-b19a-bc4e4fde0da1', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Concluir ajustes na SDR agente de IA', 'Refazer e ajustar a SDR agente de IA para eliminar erros como repetição de mensagens e garantir que não cometa erros básicos antes de colocar em produção.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'a SDR agêntica, né, de IA, eu comecei a— ela não estava, não está ainda do jeito que tem que ser, que ela ainda está errando coisa besta... eu tô validando, entendendo, e aí eu quando eu fui fazer uma mudança lá eu quebrei ela e tô refazendo', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('311d169e-98f6-437f-a544-42745837519b', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Entregar dashboard de vendas com visão de duplicados até terça', 'Finalizar o dashboard de vendas que alimenta a parte de MQL/Sales, incluindo identificação e contagem de leads duplicados, para apresentação na terça.', 'vitor', DEFAULT, NULL, 'terça que vem', 'alta', 'aberta', 'o meu Dash que eu tô fazendo, ele vai alimentar essa parte também... Então é o que tá para terça que vem, sacou?', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('95e17aa3-7921-4bf7-8fb5-631ede704ac9', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Consolidar dashboards de terça (dados de Weddings) com planilha de Speaker A', 'Após ter o dashboard de terça pronto e a planilha de Speaker A redonda, juntar as duas visões para ter leitura ponta a ponta dos dados de Weddings.', 'vitor', DEFAULT, NULL, 'depois de terça', 'media', 'aberta', 'o de terça é o meu também, aí depois a gente põe mais um prazo para juntar os dois e a gente ter de ponta a ponta', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('9f172ea7-906f-400a-a068-5640194931cd', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Definir e estruturar projeto de mapeamento e governança de dados com Isa', 'Transformar o mapeamento de dados dispersos (várias pessoas mexendo em dados) em um projeto estruturado, provavelmente liderado pela Isa, para consolidar fontes e evitar duplicidade, quando houver respiro operacional.', 'vitor', DEFAULT, NULL, 'daqui a pouco / quando sair do recomeçar', 'baixa', 'aberta', 'isso vai ser daqui a pouco, tipo, por ser o maior projeto da Isa, por exemplo... quando a gente sair um pouquinho do recomeçar, respirar, aí concentrar mesmo, centralizar tal', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b8943825-fc60-44cd-8388-28beda4aac11', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Marcelo sobre organização de relatório de acompanhamento de e-mails com Fernanda', 'Acompanhar se Marcelo organizou com a Fernanda o relatório de acompanhamento das campanhas de e-mail e próximos passos, conforme combinado.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Aí eu vou organizar com a Fernanda um relatório para a gente poder ter de acompanhamento e dos próximos passos.', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d28d8c51-e30c-46c6-820d-77372870e542', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Isa sobre validação e uso do novo site de planilha de convidados', 'Verificar com Isa/meninas de planejamento se já validaram e começaram a usar o site que gera a planilha de convidados automaticamente para a Luna/CRM.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Essa do meio aí, do ajuste da planilha da Ju, eu arrumei, né? Só precisa as meninas validar e começar a usar, que é o site lá', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('9a091ba0-7b4e-486f-90d6-8d33293f62de', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar trabalho de Speaker E no mapeamento da jornada de convidados e automações', 'Rever com Speaker E o mapeamento da jornada de convidados, incluindo ''como'' e ''o que'' é enviado, problemas e ideias de solução, em uma reunião na segunda às 13h30.', 'vitor', DEFAULT, NULL, 'segunda 13:30', 'alta', 'aberta', 'Segunda eu marco 1:30 de volta... Segunda eu marco 1:30 de volta... Te chamo segunda então.', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('fbd1fc1c-fa27-405d-a597-bcccf2aa05e1', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Orientar Speaker E na priorização e desenho de soluções para comunicação automática de convidados', 'Ajudar Speaker E a priorizar problemas, definir soluções (automatização, fluxos, mensagens) e revisar o material visual que ela está preparando sobre comunicação automática com convidados.', 'vitor', DEFAULT, NULL, 'segunda', 'media', 'aberta', 'Daí a gente entra na Eu já pausaria aí já... E aí eu já tacaria como que eu vou resolver isso, tá?... E aí eu te mostro segundo ou terça.', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('47a0ef61-fbb4-4bcc-89f2-973a8ea6f5f2', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar trabalho de Speaker F no projeto de check-in/pontos de contato e no ClickUp', 'Apoiar Speaker F na definição do plano do projeto de pontos de contato/check-in (problemas, subproblemas, prioridades, facilidades) e na criação de uma visualização no ClickUp que mostre projetos, alocação de tempo e fila de prioridades.', 'vitor', DEFAULT, NULL, 'terça de tarde', 'alta', 'aberta', 'na terça a gente fala melhor, tá bom?... Pode pôr, põe para de tarde, por favor... esse de agora do check-in, para mim ele é prioridade total... E outra coisa é o negócio do ClickUp', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f294ee53-1537-45f8-b4fe-f4aa1a501a6b', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar organização de reunião de quarta-tarde para próximos passos de leads', 'Confirmar com o time (Speaker A/Marcelo) a marcação da reunião de quarta à tarde para revisar andamento e próximos passos em relação às decisões sobre leads.', 'vitor', DEFAULT, NULL, 'quarta-tarde', 'media', 'aberta', 'podemos deixar marcado para quarta-tarde a gente sentar para ver o andamento ou minimamente os próximos passos em relação ao que a gente decidiu na terça?', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c49d3163-18d5-43bb-9c1f-77d840a7636e', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar criação de grupo para votação do nome do time', 'Acompanhar se Speaker E criou o grupo para votação do nome (grupo da Copa do Mundo/time) e participar da escolha quando o grupo estiver criado.', 'vitor', DEFAULT, NULL, NULL, 'baixa', 'aberta', 'a gente vai fazer o grupo lá para votar no nome Combinado.', '2026-06-01 16:49:57.762673+00', '2026-06-01 16:49:57.762673+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('f86f9608-13ac-4eb8-ada6-03da951d1264', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Finalizar e validar dashboard de Trips', 'Concluir o dash de Trips, validar se os dados e métricas estão corretos e só então disponibilizar/entregar, evitando repetir o problema do dash de Weddings.', 'vitor', DEFAULT, NULL, 'terça', 'alta', 'aberta', 'Eu tinha que terminar o Dash de trips, que eu não avaliei se tá correto ainda, então eu não vou entregar, porque eu me ferrei com o de weddings', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b636605b-b78a-427c-ae6e-6a2bedd14ce8', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar Vanessa sobre download das transcrições do Elephant', 'Verificar com a Vanessa se ela já falou com o pessoal do Elephant e conseguiu baixar todas as transcrições, para Vitor poder rodar o score retroativo e ajustar o Elephant.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Eu pedi para Vanessa falar com o pessoal do Elephant para a gente baixar todas as transcrições... Só que eu não cobrei a Vanessa ainda do retorno, do se ela conseguiu isso', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b746b882-cdaf-4ec1-b507-c7f9ff9123f4', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Rodar score retroativo usando dados do Elephant', 'Após receber as transcrições do Elephant, rodar o score retroativo para entender o que aconteceu nos leads anteriores e incrementar a análise de Weddings.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'se baixar todas, eu consigo rodar aqui para ele fazer retroativo. E aí a gente ajustar o elefante para ele ter o score parecido', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c6cf5c63-95b7-487d-824d-e658e21c8b5f', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Analisar impacto da primeira mensagem do SDR e evolução da conversa', 'Usar o dash já pronto para analisar se a nova primeira mensagem do SDR está aumentando o volume de leads que continuam conversando além da primeira resposta, comparando com o cenário anterior.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Mas eu vou olhar para essa análise porque essa parte do Dash já está pronta', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('c285081b-28ee-4520-b27e-4f690c52165f', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Refazer e estabilizar a SDR agente de IA', 'Consertar a SDR de IA que está repetindo mensagens e cometendo erros básicos, refazendo a configuração após a quebra e só considerar pronta quando estiver estável.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'a SDR agêntica, né, de IA, eu comecei a— ela não estava, não está ainda do jeito que tem que ser... quando eu fui fazer uma mudança lá eu quebrei ela e tô refazendo', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('216d558d-0eb8-4e1e-af20-5eda6494d9fc', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Concluir analytics de Weddings incluindo análise do índice da mentira', 'Finalizar o analytics de Weddings, incluindo a análise dos contratos fechados versus o que os clientes declararam inicialmente (investimento e número de convidados), para entregar até terça de manhã ou quarta.', 'vitor', DEFAULT, NULL, 'até terça de manhã ou quarta', 'urgente', 'aberta', 'Então esse tá até terça de manhã ou quarta, né, que é o prazo para eu terminar o analytics de weddings dessa parte, vai estar lá', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('2165131c-cf5d-4eee-a6a9-a4506c788830', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Consolidar dashboards de Weddings de Vitor e Tiago para visão ponta a ponta', 'Após Vitor e Tiago terem seus dashboards prontos na terça, combinar os dois em uma visão consolidada ponta a ponta para entender melhor o funil.', 'vitor', DEFAULT, NULL, 'depois de terça', 'media', 'aberta', 'o de terça é o meu também, aí depois a gente põe mais um prazo para juntar os dois e a gente ter de ponta a ponta', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('3db7a007-0c41-4373-86e0-5a2af9e357f6', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Definir e implementar processo de validação de dados com o time comercial (Jéssica, Sara, etc.)', 'Estruturar um momento formal e recorrente para validar números do dashboard com o time comercial, estimulando que levantem inconsistências de dados em vez de apenas comentarem informalmente.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Eu queria te pedir para que você estimule elas a falar... A gente precisa começar a usar esse Dash, eu preciso que você me ajude a validar esses números', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('79825426-d1a7-467f-970b-8b6b8789518b', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Garantir que o dashboard de Weddings mostre duplicados e impacto na conversão', 'Ajustar o dash de Weddings para evidenciar leads duplicados e seu impacto nas métricas de conversão, reforçando a confiabilidade dos dados.', 'vitor', DEFAULT, NULL, 'terça que vem', 'alta', 'aberta', 'o meu Dash que eu tô fazendo, ele vai alimentar essa parte também... os duplicados vai mostrar... Então é o que tá para terça que vem', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('2ca1b069-b798-442c-a101-d72b3b744270', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar plano de ação de Fernanda para melhorar governança de e-mails', 'Acompanhar o trabalho da Fernanda, que já está com o Active conectado, fechando o diagnóstico de e-mails e definindo prazos e metas de evolução, cobrando se necessário.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Eu já passei para Fernanda, ela já tá olhando... primeiro fechar esse diagnóstico e depois trabalhar com a gente uma ideia de prazos', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b630a7d1-1295-4663-bbff-3a7ca2c3a5e9', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar relatório de acompanhamento de e-mails que Marcelo vai organizar com Fernanda', 'Verificar se Marcelo e Fernanda organizaram o relatório de acompanhamento de e-mails e próximos passos, que servirá de base para monitorar evolução.', 'vitor', DEFAULT, NULL, 'semana que vem', 'media', 'aberta', 'Aí eu vou organizar com a Fernanda um relatório para a gente poder ter de acompanhamento e dos próximos passos', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('30d179dc-0760-4ade-8e63-4bf2aec8c5d9', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar teste pontual de ferramenta de enriquecimento de dados (Serasa ou similar)', 'Acompanhar o teste de contratar uma consulta pontual de enriquecimento (ex.: Serasa) para avaliar se ajuda a identificar perfil de clientes e se vale o investimento.', 'vitor', DEFAULT, NULL, NULL, 'baixa', 'aberta', 'bom, vamos botar um e ver se ajuda a gente ou não. Se a gente ajudar, a gente avalia se vale o investimento', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('9bd2e743-e895-464a-8f0f-df546b18b9d8', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Validar e acompanhar mapeamento da jornada de convidados e automações feito por Speaker E', 'Rever o mapeamento da jornada de convidados (como/que mensagens são enviadas, automações, problemas) que Speaker E está estruturando, ajudando a priorizar soluções e automações.', 'vitor', DEFAULT, '2026-06-01 13:30:00+00', 'segunda 13:30', 'alta', 'aberta', 'Segunda eu marco 1:30 de volta... Segunda eu marco 1:30 de volta... Te chamo segunda então', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('b63a5b35-3467-4b7e-819c-53236a46bc5f', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar validação do novo site de convidados pelas meninas de planejamento', 'Confirmar com as meninas de planejamento se elas já validaram e começaram a usar o novo site que gera a planilha de convidados automaticamente para a Ju/Luna.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Essa do meio aí, do ajuste da planilha da Ju, eu arrumei, né? Só precisa as meninas validar e começar a usar', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('35e7da5a-70e9-4134-9e93-97071fb947a5', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Definir regras de automação para respostas de convidados (vou/não vou e família)', 'Especificar a lógica de automação para quando o convidado responde que não vai ou vai (incluindo se é só ele ou a família inteira), para ajustar fluxos e mensagens no CRM.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Quando a pessoa responder que não vai, aí a gente vai puxar quem mais tá com ela e aí pergunta: não vai só você ou não vai todo mundo?', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('978c911f-6981-489f-820c-05fe8ece9061', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar trabalho de Speaker E sobre lista de 600 convidados extras', 'Acompanhar o estudo que Speaker E fará sobre a lista de 600 pessoas extras para avaliar complexidade e definir se será um disparo amplo ou testes menores.', 'vitor', DEFAULT, NULL, 'segunda ou terça', 'media', 'aberta', 'Trabalhar nisso então, nesse problema que a gente já tem... E aí eu te mostro segundo ou terça', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('ec18dd2b-f5c1-4ced-82d6-d5ee5f0926c0', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Orientar Speaker F na priorização de problemas e subproblemas do projeto de check-in', 'Ajudar Speaker F a mapear problemas, subproblemas, prioridades e facilidade de resolução no projeto de check-in/pontos de contato, conforme combinado.', 'vitor', DEFAULT, '2026-06-02 15:00:00+00', 'terça à tarde', 'alta', 'aberta', 'E aí na terça a gente fala melhor, tá bom?... Pode pôr, põe para de tarde, por favor', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('db351f92-517f-48ff-a7b2-0313514c11da', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Acompanhar mapeamento de problemas de check-in e plano de solução feito por Speaker F', 'Verificar se Speaker F mapeou problemas, subproblemas e possíveis soluções para o fluxo de check-in/pontos de contato, revisando com ela na reunião de terça.', 'vitor', DEFAULT, '2026-06-02 15:00:00+00', 'terça à tarde', 'alta', 'aberta', 'Mas aí você vai ver se você já vai ter conseguido fazer esse mapeamento dos problemas, subproblemas, e como que você arrumaria cada um deles', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('acc5b3d6-ab7c-40bb-aa24-7294ce27f01b', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Definir estrutura de visualização no ClickUp para acompanhar projetos e carga de trabalho', 'Especificar com Speaker F (e possivelmente Cláudio) uma visualização no ClickUp que permita ver rapidamente em que projetos cada pessoa está, há quanto tempo e qual o próximo da fila.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'outra coisa é o negócio do ClickUp... uma página só que eu conseguisse saber o que tá acontecendo... a Isa tá nesse projeto do check-in, ela gasta x%', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('d7dd14ce-2526-4180-9ffe-008b4440a61b', 'c429d48d-1cd2-4713-a26f-65489518a699', 'Cobrar criação de visualização no ClickUp com o Cláudio', 'Acompanhar com Speaker F e Cláudio a criação de uma visualização no ClickUp que permita ver múltiplas pessoas e projetos, conforme necessidade de Vitor.', 'vitor', DEFAULT, NULL, NULL, 'baixa', 'aberta', 'Ontem comecei a dar uma olhadinha em relação ao ClickUp, que o Cláudio, ele consegue, tipo, você pede para ele, ele cria lá', '2026-06-01 16:50:07.041462+00', '2026-06-01 16:50:07.041462+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', NULL, NULL, NULL, NULL);
INSERT INTO public.tarefas VALUES ('e798bcef-b94a-475d-b73a-134dc8471998', 'c7896b53-7008-4cdc-82ed-6900220327ee', 'Cobrar envolvimento da Isa na organização e limpeza dos dados de casamentos', 'Acompanhar para que Isa seja de fato alocada para organizar e limpar os dados extraídos (planilhas, itens, valores), deixando tudo estruturado e pronto para análise.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'Dá até para colocar, eu posso olhar ver como que a Isa tá de trampo, dá para colocar Isa para fazer isso aí, porque ela consegue fazer essa organização tal, deixar bonitinho.', '2026-06-08 13:00:46.344362+00', '2026-06-08 13:00:46.344362+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Isa"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('3d8f8c1e-4e53-40a8-a9b6-6bfc1eba30a6', 'c7896b53-7008-4cdc-82ed-6900220327ee', 'Cobrar levantamento dos principais itens contratados e estatísticas de valor nos casamentos', 'Garantir que, a partir dos dados limpos, a equipe produza um relatório com os principais itens contratados em todos os casamentos e seus valores médio/mediana, mínimo e máximo.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Preciso descobrir duas coisas mais importantes, quais são os os principais itens que são contratados em todos os casamentos e o valor médio, mínimo e o máximo. Dá para fazer, na verdade, uma mediana, é melhor.', '2026-06-08 13:00:46.344362+00', '2026-06-08 13:00:46.344362+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Isa"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('bcd0e3a7-d1f6-470e-92d2-d0109e9a20dc', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Construir matriz de valor mínimo e médio por tipo de fornecedor e destino', 'Levantar, junto com times de operação/produção e marketing, o valor mínimo e médio por tipo de fornecedor/serviço em cada destino relevante, para criar uma matriz que permita estimar o custo total de casamento com faixas de variação.', 'Tiago', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Já é a primeira coisa que a gente tem que fazer, construir isso aí.', '2026-06-08 13:09:51.49392+00', '2026-06-08 16:48:00.532389+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'a7cb00b5-5fa0-491f-b5e5-2b2ebf0085c6', NULL, '[]', 'Produto');
INSERT INTO public.tarefas VALUES ('0fbce5e8-0381-4f89-ae20-134a081c52c4', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Definir e documentar tarefas da reunião em um grupo específico no Teams', 'Criar um grupo no Teams focado neste projeto de melhoria de funil/closer e, em seguida, listar lá os to-dos com responsáveis e datas para cada ação combinada na reunião.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'vale a pena a gente criar um grupo disso aqui, não só o grupo da reunião, e lá a gente definir as tarefas, quem vai fazer, como vai ser e tal, para a gente de fato tá, cara, cada pessoa tá fazendo tal coisa.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'b0c52b7f-577f-4c73-a3f9-322470dfa96a', NULL, '[]', 'Vendas/SDR');
INSERT INTO public.tarefas VALUES ('2c367406-51a2-473b-954e-1c6f586a713b', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar criação do grupo no Teams para o projeto de melhoria de funil', 'Acompanhar se alguém da equipe criou o grupo no Teams para este tema, conforme pedido no final da reunião, para que Vitor possa enviar os to-dos e prazos.', '?', DEFAULT, NULL, NULL, 'alta', 'aberta', 'se alguém já puder criar o grupo no Teams ali. E aí depois eu mando os to-dos bonitinho', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'b0c52b7f-577f-4c73-a3f9-322470dfa96a', NULL, '[]', 'Vendas/SDR');
INSERT INTO public.tarefas VALUES ('4228326f-d7f8-438f-9cca-c457210bdccb', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Montar e enviar lista de to-dos detalhada no grupo do Teams', 'Após o grupo no Teams ser criado, Vitor deve montar os to-dos com responsáveis e datas e enviar para todos no grupo, consolidando as ações da reunião.', 'vitor', DEFAULT, NULL, 'depois da criação do grupo no Teams', 'alta', 'aberta', 'Mas aí eu monto nos to-do direitinho e mando para todos num grupo.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', 'b0c52b7f-577f-4c73-a3f9-322470dfa96a', NULL, '[]', 'Vendas/SDR');
INSERT INTO public.tarefas VALUES ('6940e351-787e-4cbe-acf6-0b91233080e3', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar envio da planilha de casamentos e resultados que Tiago mostrou', 'Garantir que Tiago envie a planilha com dados de contratos, destinos, faturamento e margem que ele apresentou, para Vitor usar nos cruzamentos com Active.', 'Tiago', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Essa aqui, tá? Mando já, tá bom.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Tiago"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('ad71480a-cd54-463d-aad7-97cfeac3faba', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cruzar planilha de casamentos do Mundi com contatos e deals do Active', 'Usar a planilha que Tiago vai enviar (com CPF, destino, tipo de contrato, faturamento e margem) para cruzar com os contatos e deals do Active, identificando perfis de casamento mais rentáveis e diferenças entre o que o lead declarou e o que fechou.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'Se você conseguir já me trazer isso com o CPF do, do, de quem fechou, sabe? Porque aí eu consigo bater, já que eu fiz o push dos contatos, vai ter o CPF lá, né, no Active. Aí dá para bater, dá para cruzar com qual deal que era.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Tiago"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('6f39aec6-d7fb-476a-a074-e5393703152e', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Envolver Roni para ajudar a levantar médias de investimento por perfil de lead', 'Articular com Roni para que ele ajude a extrair e estruturar dados históricos (ex.: 2025, 3.400 leads) e aplicar fórmulas de score em massa, identificando quais perfis de lead fecham mais.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Eu acho que é o Roni, ele pode ajudar nisso. Nesse momento aí talvez seja mais indicado.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Roni"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('2ccc5a97-b08e-4200-8d10-12c171720051', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar validação semanal dos números do Active com testes práticos', 'Acompanhar se o time está fazendo "provas reais" dos números do Active (abrir relatório do período atual, mudar alguns deals no Active e verificar o reflexo), garantindo confiança contínua nos dados e evitando planilhas paralelas.', '?', DEFAULT, NULL, 'próximas semanas', 'alta', 'aberta', 'Façam esse teste de assim, vamos pegar o recorte dessa próxima semana de tudo que elas mexeram no Active e bate, sabe? Puxa aí só a data da semana e vê o que aconteceu, para, sei lá, validar o que que tá sendo feito.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '[]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('a6928880-9858-4364-8016-3929124470eb', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar análise do pitch de closer de agosto–novembro do ano passado versus hoje', 'Garantir que alguém (provavelmente Vani/Diana/time de closer) revise gravações e materiais do período bom (ago–nov) e compare com o discurso atual, identificando mudanças de conteúdo, ordem e forma de apresentar valores e pagamentos.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'uma é entender qual que era a diferença do que a gente apresentava nesse período aí que o Thiago falou, né, do ano passado, sei lá, até agosto, janeiro até agosto do ano passado, se tinha alguma coisa de diferente, né.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'ecb6bbc0-b1e2-473a-9d8f-09f22b581c62', NULL, '["Vani", "Diana"]', 'Weddings');
INSERT INTO public.tarefas VALUES ('f6d17b31-da34-43e7-8df4-74894ea0195a', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar levantamento de score para contratos fechados do ano passado e deste ano', 'Acompanhar o trabalho de score manual que está sendo feito para todos os contratos fechados do ano passado e deste ano, garantindo conclusão e análise conjunta com Vani.', 'Speaker C', DEFAULT, NULL, NULL, 'media', 'aberta', 'Estou fazendo score para aquele score lá automático, é de todos os contratos fechados do ano passado e todos desse ano até agora. ... Daí eu e a Vani vamos analisar isso, bater a diferença.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '["Vani"]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('aad298f1-08cd-4193-89e2-90c0e3c48a4d', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar extração de dados de convidados e contratação real via Mundi', 'Garantir que alguém baixe do Mundi uma planilha com o que as pessoas efetivamente contrataram (incluindo quantidade de convidados), para complementar os dados do Active e alimentar a análise de perfis de casamento.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'A gente consegue bater esse dado, Vitor, pelo Mundi. A gente consegue baixar uma planilha de Excel do Mundi com o que as pessoas contrataram.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', '670c35c1-25da-4869-8855-bac91b6f9590', NULL, '[]', 'Dados & Dashboards');
INSERT INTO public.tarefas VALUES ('a684b0b5-6ba9-42bf-9c35-448cd9d0b7b8', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Ajustar critérios de MQL para priorizar leads com investimento de 50–200k e Caribe/Itália', 'Rever, junto com marketing, os critérios de qualificação e segmentação para reduzir volume de leads até 50k (especialmente Nordeste) e aumentar leads de 50–200k e destinos Caribe/Itália, alinhando com os dados de fechamento.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'A gente precisa ajustar o MQL para esses níveis aqui de 100 a 200, de 80 mil para cima e coisas do tipo. É aí que o marketing precisa começar a olhar', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '4100263a-e4cb-4a7f-a741-44666728339e', NULL, '[]', 'Marketing');
INSERT INTO public.tarefas VALUES ('99113603-6c2a-4f8e-ace5-f94ec4b7ac6f', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar definição de plano de ação com Marcelo para aumentar leads de Caribe', 'Conversar com Marcelo para entender a justificativa atual sobre Caribe e definir ações imediatas de marketing/aquisição para aumentar o volume de leads dessa região.', 'vitor', DEFAULT, NULL, NULL, 'alta', 'aberta', 'A gente entender com o Marcelo a justificativa ou o plano de ação para que a gente ataque o Caribe.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '4100263a-e4cb-4a7f-a741-44666728339e', NULL, '["Marcelo"]', 'Marketing');
INSERT INTO public.tarefas VALUES ('b37790d5-e786-449a-b062-363ae931c21a', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Especificar e encomendar materiais visuais com marketing para destinos prioritários', 'Briefar Ângela e o time de marketing para criar vídeos e materiais visuais (apresentação, site/landing page) específicos para Caribe e outros destinos prioritários, a serem usados por Sarah e closers nas interações com leads.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'a gente pode pedir— esqueci o nome— Ângela? ... Pedir ajuda do marketing para deixar isso visualmente bonito, né? Na apresentação e tal, na hora de mostrar ou num sitezinho, sei lá, a gente vê como que faz.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '4100263a-e4cb-4a7f-a741-44666728339e', NULL, '["Ângela"]', 'Marketing');
INSERT INTO public.tarefas VALUES ('bb5157c5-7498-458d-8438-4e1d14f108a8', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Desenhar conceito de landing pages dedicadas e vídeos de encantamento por região', 'Definir, em alto nível, como serão as landing pages dedicadas e vídeos de encantamento para regiões como Caribe (conteúdo, objetivos, uso no funil), para depois passar o briefing detalhado ao marketing.', 'vitor', DEFAULT, NULL, NULL, 'media', 'aberta', 'Eu penso duas coisas: landing page dedicada para esse tipo de região e vídeo. Ainda mais que a Ângela faz um vídeo muito foda em duas horinhas.', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'executar', '4100263a-e4cb-4a7f-a741-44666728339e', NULL, '["Ângela"]', 'Marketing');
INSERT INTO public.tarefas VALUES ('ab7dcf56-cadb-415a-bfb7-76aa17c9a804', '9308f6d4-9bf6-4d8e-85c4-28e64b98cc47', 'Cobrar produção de material interativo para estimativa de investimento de casamento', 'Acompanhar a criação de um documento/página interativa que permita montar um casamento com itens obrigatórios, faixas de valor e total estimado, para ser usado na reunião de closer e reduzir frustração dos clientes.', '?', DEFAULT, NULL, NULL, 'media', 'aberta', 'de repente a gente a gente produzir um material bem legal, bem atraente assim, que talvez seja interativo, que faça sentido, sabe? Pensar assim, o casamento de R$150 mil inclui 10 itens que variam de tanto a tanto', '2026-06-08 13:09:51.49392+00', '2026-06-08 13:09:51.49392+00', NULL, NULL, '7740e829-9462-416b-81a1-b787e23ba9b2', 'cobrar', 'a7cb00b5-5fa0-491f-b5e5-2b2ebf0085c6', NULL, '[]', 'Produto');
INSERT INTO public.tarefa_eventos VALUES ('3b617b66-19eb-46e2-a7f6-01bccbb78c9a', '7da4bcfa-2499-4272-b3e7-8114d5b971ad', 'concluida', '{"status": "concluida"}', '2026-05-21 22:34:14.805899+00');
