INSERT INTO public.tarefa_eventos VALUES ('9014d26c-d22d-4b88-bc92-c2e9f98abd79', '9b2fea80-a991-4b7b-a3c1-755d664ade81', 'concluida', '{"status": "concluida"}', '2026-05-21 22:34:35.504124+00');
INSERT INTO public.tarefa_eventos VALUES ('045284f1-25fd-4981-9df7-60accf2fec0a', '0be62be1-9c25-4238-b0bd-2378abb4614c', 'reaberta', '{"owner": "Diana", "prazo": null, "status": "aberta", "titulo": "Escrever o básico da vaga de responsável por convidados e enviar até sexta", "descricao": "Vitor combinou de escrever o básico da descrição da vaga para a área de convidados e enviar até sexta para os outros revisarem, antes da reunião de alinhamento na terça.", "prazo_text": "até sexta", "prioridade": "alta"}', '2026-05-22 00:41:40.27807+00');
INSERT INTO public.tarefa_eventos VALUES ('2571cfaf-ce80-47ef-918b-cb997322cc6c', 'd30dc884-9820-4bf5-86fc-ba77259d5af1', 'reaberta', '{"owner": "Ana", "prazo": "2026-05-27T02:59:00.000Z", "status": "aberta", "titulo": "Cobrar da Ana o mapeamento completo dos processos e problemas de convidados", "descricao": "Vitor combinou de orientar a Ana a mapear tudo (processos, problemas, tipos de comunicação, etc.) na área de convidados e trazer esse levantamento para ele, como base para redesenhar o fluxo e dar feedbacks.", "prazo_text": null, "prioridade": "alta"}', '2026-05-25 23:42:14.157993+00');
